import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"梅尔文·沃尔夫","description":"","frontmatter":{"title":"梅尔文·沃尔夫","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/梅尔文·沃尔夫.md","filePath":"04_people/梅尔文·沃尔夫.md"}'),l={name:"04_people/梅尔文·沃尔夫.md"};function n(i,t,s,_,p,d){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="梅尔文·沃尔夫" tabindex="-1">梅尔文·沃尔夫 <a class="header-anchor" href="#梅尔文·沃尔夫" aria-label="Permalink to &quot;梅尔文·沃尔夫&quot;">​</a></h1><ul><li><strong>角色职位</strong>：明星家具（Star Furniture）创始人兼 CEO</li><li><strong>与巴菲特关系</strong>：被伯克希尔·哈撒韦收购的子公司创始人/CEO</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>梅尔文·沃尔夫是明星家具（Star Furniture）的创始人和长期领导者。明星家具是美国知名的家具零售商，主要服务于中南部市场，在得克萨斯州等地拥有多家门店。作为创始人，沃尔夫一手打造了这家从区域家具店成长为行业标杆的企业，其经营哲学强调以合理价格为顾客提供可靠的家具产品。</p><p>伯克希尔·哈撒韦对明星家具的收购，体现了巴菲特一贯的投资标准——由优秀的管理者运营的优质企业。沃尔夫作为创始人CEO，不仅建立了可信赖的品牌声誉，更培养了一支稳定的管理团队。在伯克希尔的控股下，明星家具保持了独立运营的灵活性，同时获得了资本层面的支持。</p><p>沃尔夫的领导风格务实低调，注重与顾客和员工建立长期信任关系。这种特质与巴菲特欣赏的&quot;受信赖的品牌&quot;投资理念高度契合，也解释了为何明星家具能够成为伯克希尔消费板块的重要组成部分。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>创立年份</strong>：梅尔文·沃尔夫创立明星家具，逐步将其发展为得克萨斯州及周边地区领先的家具零售商</li><li><strong>被收购年份</strong>：明星家具被伯克希尔·哈撒韦收购，沃尔夫继续担任 CEO 主导日常运营</li><li><strong>后续发展</strong>：在伯克希尔旗下保持稳定运营，作为伯克希尔保险之外消费业务的重要补充</li></ul>',8)])])}const h=a(l,[["render",n]]);export{c as __pageData,h as default};
